1. question='The country for Gado-gado was what?'; answer='Indonesia'; support_paragraph=11
2. question='#1 –Timor Leste Commission of Truth and Friendship >> country'; answer='East Timor'; support_paragraph=9
3. question='who is the president of newly declared independent country #2'; answer='Francisco Guterres'; support_paragraph=14

